CREATE TABLE tasks (id UUID PRIMARY KEY, course_id UUID REFERENCES courses(id) ON DELETE SET NULL, title VARCHAR(240) NOT NULL, description TEXT, due_at TIMESTAMPTZ, status VARCHAR(24) NOT NULL, priority VARCHAR(24) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ);
CREATE INDEX idx_tasks_course_status ON tasks(course_id, status);
CREATE TABLE quizzes (id UUID PRIMARY KEY, course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE, title VARCHAR(200) NOT NULL, knowledge_point VARCHAR(160), status VARCHAR(24) NOT NULL, created_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ);
CREATE TABLE questions (id UUID PRIMARY KEY, quiz_id UUID NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE, content TEXT NOT NULL, type VARCHAR(32) NOT NULL, options_json TEXT NOT NULL, correct_answer VARCHAR(500) NOT NULL, explanation TEXT, knowledge_point VARCHAR(160) NOT NULL);
CREATE TABLE answer_records (id UUID PRIMARY KEY, quiz_id UUID NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE, question_id UUID NOT NULL REFERENCES questions(id) ON DELETE CASCADE, course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE, knowledge_point VARCHAR(160) NOT NULL, user_answer VARCHAR(500), correct BOOLEAN NOT NULL, answered_at TIMESTAMPTZ NOT NULL, CONSTRAINT uk_answer_records_question UNIQUE(quiz_id, question_id));
CREATE INDEX idx_answers_course_point ON answer_records(course_id, knowledge_point);
